boot=base/'boot';boot.mkdir()
payload={'update_once_r12.py': {'base64': '', 'sha256': '1b1fd097b05208b7d977e7964efe44fa468d93f3786431a5218c4be76f802dcc', 'bytes': 5908}, 'launch_update_r12.sh': {'base64': '', 'sha256': 'cd1374b57a7d7db6f258dc23335ac0d660dc3a9da60d70525a956762dee5cd83', 'bytes': 450}}
for name,value in payload.items():
 raw=base64.b64decode(value['base64'],validate=True)
