print(json.dumps({'phase':'NATIVE_TOOLCHAIN_ARCHIVE_READY','sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw),'files':len(paths),'source_bytes':sum(x.stat().st_size for x in paths),'base64':base64.b64encode(raw).decode(),'runtime_pid':int(pid),'pane_exit':int(parts[4]),'result_sha256':hashlib.sha256(result.read_bytes()).hexdigest(),'result_bytes':result.stat().st_size},ensure_ascii=False),flush=True)
